/** Typed graph for User Flow Explorer — generated by scripts/user-flow-explorer/generate-graph.ts */

export type UserFlowRole = "PUBLIC" | "STUDENT" | "COACH" | "ADMIN";

export type FlowViewId =
  | "all"
  | "student"
  | "coach"
  | "admin"
  | "auth"
  | "journey";

export type EdgeKind = "navigation" | "conditional" | "modal" | "redirect" | "auth";

export type ScreenCategory =
  | "auth"
  | "student"
  | "coach"
  | "admin"
  | "join"
  | "internal"
  | "redirect";

export type FlowScreenNode = {
  id: string;
  route: string;
  title: string;
  category: ScreenCategory;
  roles: UserFlowRole[];
  componentPath: string;
  isDynamic: boolean;
  /** Relative to /public or graph data dir */
  screenshotPath: string | null;
  screenshotStatus: "captured" | "placeholder" | "missing" | "manual_review";
  sourceFiles: string[];
  notes: string[];
};

export type FlowNavigationEdge = {
  id: string;
  source: string;
  target: string;
  label: string;
  kind: EdgeKind;
  roles: UserFlowRole[];
  verified: boolean;
  sourceFile?: string;
  condition?: string;
};

export type FlowGraphMeta = {
  generatedAt: string;
  appVersion: string;
  scannerVersion: string;
  routeCount: number;
  edgeCount: number;
  manualReviewCount: number;
};

export type FlowGraph = {
  meta: FlowGraphMeta;
  nodes: FlowScreenNode[];
  edges: FlowNavigationEdge[];
};

export type PersistedNodeLayout = {
  x: number;
  y: number;
};

export type FlowLayoutState = {
  version: 1;
  updatedAt: string;
  positions: Record<string, PersistedNodeLayout>;
};

export type UxAuditFindingKind =
  | "orphan"
  | "dead_end"
  | "missing_back"
  | "long_journey"
  | "duplicate_destination"
  | "excessive_branching"
  | "role_inconsistency";

export type UxAuditFinding = {
  kind: UxAuditFindingKind;
  severity: "info" | "warning" | "error";
  verified: boolean;
  screenId?: string;
  edgeId?: string;
  message: string;
  recommendation?: string;
};

export type JourneyPreset = {
  id: string;
  label: string;
  role: UserFlowRole;
  startRoute: string;
  endRoute: string;
  description?: string;
};
